    id: "dsa-m22-219",
    number: "DSA-M22-219",
    title: "Machine-coding DSA mock",
    difficulty: "Hard",
    experienceLevel: "5–8 Years / 8+ Years",
    category: "Mock Coding Interviews",
    expectedAnswer: "A machine-coding mock should test whether the candidate can combine data structures, APIs, edge-case handling, and maintainable code. A representative exercise is implementing an LRU cache with O(1) get and set.",
    deepExplanation: "Step 1 — Understand the interview requirement.\n\nStep 1 — Use a Map for lookup and a doubly linked list for recency.\n\nWITHOUT BUILT-IN:\n```ts\nclass LruNode<K, V> {\n  constructor(\n    public key: K,\n    public value: V,\n    public prev: LruNode<K, V> | null = null,\n    public next: LruNode<K, V> | null = null,\n  ) {}\n}\n\nclass LRUCache<K, V> {\n  private readonly map = new Map<K, LruNode<K, V>>();\n  private readonly head = new LruNode<K, V>(undefined as K, undefined as V);\n  private readonly tail = new LruNode<K, V>(undefined as K, undefined as V);\n\n  constructor(private readonly capacity: number) {\n    this.head.next = this.tail;\n    this.tail.prev = this.head;\n  }\n\n  get(key: K): V | undefined {\n    const node = this.map.get(key);\n    if (!node) return undefined;\n\n    this.remove(node);\n    this.addAfterHead(node);\n    return node.value;\n  }\n\n  set(key: K, value: V): void {\n    if (this.capacity <= 0) return;\n\n    const existing = this.map.get(key);\n\n    if (existing) {\n      existing.value = value;\n      this.remove(existing);\n      this.addAfterHead(existing);\n      return;\n    }\n\n    const node = new LruNode(key, value);\n    this.map.set(key, node);\n    this.addAfterHead(node);\n\n    if (this.map.size > this.capacity) {\n      const leastRecent = this.tail.prev;\n\n      if (leastRecent && leastRecent !== this.head) {\n        this.remove(leastRecent);\n        this.map.delete(leastRecent.key);\n      }\n    }\n  }\n\n  private remove(node: LruNode<K, V>): void {\n    node.prev!.next = node.next;\n    node.next!.prev = node.prev;\n  }\n\n  private addAfterHead(node: LruNode<K, V>): void {\n    node.next = this.head.next;\n    node.prev = this.head;\n    this.head.next!.prev = node;\n    this.head.next = node;\n  }\n}\n```\n\nWITH BUILT-IN:\n```ts\nfunction createMapLru<K, V>(capacity: number) {\n  const cache = new Map<K, V>();\n\n  return {\n    get(key: K): V | undefined {\n      const value = cache.get(key);\n      if (value === undefined) return undefined;\n\n      cache.delete(key);\n      cache.set(key, value);\n      return value;\n    },\n\n    set(key: K, value: V): void {\n      cache.delete(key);\n      cache.set(key, value);\n\n      while (cache.size > capacity) {\n        const oldest = cache.keys().next().value as K | undefined;\n        if (oldest === undefined) break;\n        cache.delete(oldest);\n      }\n    },\n  };\n}\n```\n\nExample:\ncapacity 2\nset(A), set(B), get(A), set(C)\n→ B is evicted.\n\nComplexity:\nMap + linked list O(1) get/set/eviction; O(capacity) memory.\n\nMachine-coding takeaway:\nExplain API, invariants, edge cases, cleanup, and testability—not only the algorithm.\n\nStep 5 — Interview takeaway:\nExplain the invariant, complexity, edge cases, and why the optimization is correct.",
